function background(){
 const sky=ctx.createLinearGradient(0,0,0,320);sky.addColorStop(0,'#506c70');sky.addColorStop(.58,'#b3a68a');sky.addColorStop(1,'#e1bd87');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // hazy Kyiv skyline
 ellipse(770,139,62,53,'#f8d38b22');ellipse(770,139,40,37,'#fce5b32c');
 // far buildings
