 for(let i=0;i<far.length;i++){const [x,y,w,h]=far[i];ctx.fillStyle=['#68716c','#717a72','#65716e','#7c8175'][i%4];ctx.fillRect(x,y,w,h);ctx.fillStyle='#ded0a144';for(let j=0;j<5;j++)for(let k=0;k<4;k++)ctx.fillRect(x+8+j*19,y+10+k*16,7,5);ctx.fillStyle='#303c3c66';ctx.fillRect(x,y+h-10,w,10)}
 // Motherland silhouette
 ctx.save();ctx.translate(784,215);ctx.strokeStyle='#77776c';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(0,15);ctx.lineTo(-1,-33);ctx.lineTo(-8,-60);ctx.lineTo(-7,-77);ctx.moveTo(-2,-30);ctx.lineTo(-23,-53);ctx.moveTo(-3,-34);ctx.lineTo(17,-57);ctx.moveTo(-4,-68);ctx.lineTo(-24,-88);ctx.moveTo(-7,-73);ctx.lineTo(17,-96);ctx.stroke();ellipse(-7,-84,5,7,'#77776c');ctx.restore();
 // golden dome and church silhouette
 ctx.fillStyle='#b8aa87';ctx.fillRect(426,203,44,37);ctx.beginPath();ctx.ellipse(448,203,24,12,0,Math.PI,0);ctx.fill();ctx.fillStyle='#a98b47';ctx.beginPath();ctx.ellipse(448,194,12,9,0,Math.PI,0);ctx.fill();ctx.fillRect(447,180,2,10);ctx.fillRect(438,229,4,8);ctx.fillRect(454,229,4,8);
 // vanishing street and sidewalk
 poly([[0,230],[1000,230],[1000,625],[0,625]],'#363c39');poly([[0,240],[410,240],[200,625],[0,625]],'#7b7869');poly([[590,240],[1000,240],[1000,625],[800,625]],'#706f62');poly([[410,240],[590,240],[1000,625],[0,625]],'#454b47');
 // curb edges and roadway markings
 ctx.strokeStyle='#d5ccaa';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(410,240);ctx.lineTo(0,625);ctx.moveTo(590,240);ctx.lineTo(1000,625);ctx.stroke();
 // pavements tile perspective
 ctx.strokeStyle='#d7cfb226';ctx.lineWidth=1;for(let i=1;i<14;i++){let t=i/14,y=240+t*t*385;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(410*(1-t),y);ctx.moveTo(590+410*t,y);ctx.lineTo(1000,y);ctx.stroke()}for(let x=45;x<410;x+=58){ctx.beginPath();ctx.moveTo(410,x/410*385+240);ctx.lineTo(x,625);ctx.stroke()}for(let x=610;x<1000;x+=58){ctx.beginPath();ctx.moveTo(590+(x-590)/410*0,240);ctx.lineTo(x,625);ctx.stroke()}
 // road cracks / lane dashes
 ctx.strokeStyle='#d6d0b040';ctx.lineWidth=2;ctx.setLineDash([26,23]);ctx.beginPath();ctx.moveTo(500,264);ctx.lineTo(500,625);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#1f2925';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(99,407);ctx.lineTo(178,399);ctx.moveTo(704,505);ctx.lineTo(781,493);ctx.moveTo(326,547);ctx.lineTo(366,532);ctx.stroke();
 // architectural framing left/right, storefronts
 poly([[0,73],[209,94],[284,270],[0,269]],'#313d3c');poly([[0,95],[180,110],[230,226],[0,227]],'#687069');poly([[0,95],[180,110],[180,126],[0,113]],'#c0b392');poly([[0,226],[230,226],[240,248],[0,248]],'#293333');
 // windows left
 for(let row=0;row<2;row++)for(let i=0;i<4;i++){let x=15+i*44,y=130+row*49;rr(x,y,28,34,1,'#344442','#b7b09c');ctx.fillStyle='#ddc9964a';ctx.fillRect(x+3,y+3,10,26)}
 poly([[1000,65],[786,94],[715,270],[1000,267]],'#35413e');poly([[1000,92],[820,110],[770,226],[1000,226]],'#777466');poly([[1000,92],[820,110],[820,126],[1000,113]],'#c9b894');poly([[1000,226],[770,226],[760,248],[1000,248]],'#303937');
 for(let row=0;row<2;row++)for(let i=0;i<4;i++){let x=842+i*42,y=130+row*49;rr(x,y,27,34,1,'#394744','#b8ae98');ctx.fillStyle='#e4cf9b50';ctx.fillRect(x+3,y+3,9,26)}
 // shop awnings/signs
 poly([[0,188],[228,188],[234,207],[0,207]],'#c9d0ad');ctx.fillStyle='#28413b';ctx.font='bold 14px sans-serif';ctx.fillText('КАВА  •  KYIV',33,202);poly([[770,188],[1000,188],[1000,207],[762,207]],'#d2d0b0');ctx.fillStyle='#3d4435';ctx.fillText('ПЕКАРНЯ',855,202);
 // street lamps
 for(const [x,y,h] of [[351,221,104],[647,221,104],[265,236,65],[735,236,65]]){ctx.strokeStyle='#303b39';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x,y-h);ctx.lineTo(x+(x<500?15:-15),y-h-8);ctx.stroke();ellipse(x+(x<500?15:-15),y-h-8,6,3,'#f8d793');}
 // trees
 for(const [x,y,r] of [[308,236,30],[692,236,32],[245,254,21],[755,254,23]]){ctx.fillStyle='#465342';ctx.fillRect(x-3,y-r/2,6,r);ellipse(x,y-r*.65,r,r*.75,'#586a4e');ellipse(x-9,y-r*.76,r*.6,r*.55,'#65734f');ellipse(x+10,y-r*.77,r*.56,r*.54,'#4e614a')}
 // warm film grain / vignette
 const vg=ctx.createRadialGradient(500,330,210,500,330,630);vg.addColorStop(0,'#0000');vg.addColorStop(1,'#07100c80');ctx.fillStyle=vg;ctx.fillRect(0,0,W,H);
}
function screenX(x){return x-cam}
function groundY(z){return 246+z*350}
function drawShadow(x,y,s){ellipse(x,y-2,24*s,8*s,'#10161270')}
function drawToad(x,y,scale,face,frame,kind='player',attack=0,invuln=0){
 const green=kind==='player'?'#9cdb42':kind==='heavy'?'#dc7953':'#d18b53',dark=kind==='player'?'#4b792d':kind==='heavy'?'#774237':'#724633',belly=kind==='player'?'#d8dc8d':'#d8b27e';
 if(invuln>0&&Math.floor(performance.now()/75)%2===0)return;
 ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);const bob=Math.sin(frame*10)*1.6;
 // legs / feet
 const stride=Math.sin(frame*10)*4;
 ellipse(-10+stride,0,12,6,dark);ellipse(12-stride,-1,12,6,dark);ctx.fillStyle=green;ctx.beginPath();ctx.ellipse(-9+stride,-9,7,13,-.25,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(9-stride,-10,7,13,.25,0,Math.PI*2);ctx.fill();
 // body
 const body=ctx.createRadialGradient(-7,-35,2,0,-29,33);body.addColorStop(0,kind==='player'?'#d0ff72':'#f1ae72');body.addColorStop(.55,green);body.addColorStop(1,dark);ctx.fillStyle=body;ctx.beginPath();ctx.ellipse(0,-29+bob,23,27,.02,0,Math.PI*2);ctx.fill();
 // belly armor
 ctx.fillStyle=belly;ctx.beginPath();ctx.ellipse(0,-23+bob,13,16,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#737d4b88';ctx.lineWidth=1;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(-7,-28+i*6+bob);ctx.quadraticCurveTo(0,-26+i*6+bob,7,-28+i*6+bob);ctx.stroke()}
 // arms and gloves
 const wind=attack>0?Math.sin((1-attack)*Math.PI)*18:0;const side=face;
 ctx.strokeStyle=green;ctx.lineWidth=10;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-15,-39+bob);ctx.lineTo(-25,-22+bob+stride*.3);ctx.moveTo(15,-39+bob);ctx.lineTo(23+wind*side,-26+bob);ctx.stroke();
 const glove=kind==='player'?'#f1a634':'#6b4034';ellipse(-26,-20+bob+stride*.3,9,7,glove);ellipse(24+wind*side,-24+bob,10,8,glove);
 // head
 ctx.fillStyle=green;ctx.beginPath();ctx.ellipse(0,-58+bob,23,18,0,0,Math.PI*2);ctx.fill();
 // eyes
 for(const ex of [-10,10]){ellipse(ex,-65+bob,8,8,'#f5efcc');ellipse(ex+face*2,-65+bob,3,4,'#1a271b')}
 // brows and grin
 ctx.strokeStyle=dark;ctx.lineWidth=2.2;ctx.beginPath();ctx.moveTo(-17,-72+bob);ctx.lineTo(-5,-70+bob);ctx.moveTo(5,-70+bob);ctx.lineTo(17,-72+bob);ctx.stroke();ctx.strokeStyle='#344522';ctx.beginPath();ctx.moveTo(-9,-52+bob);ctx.quadraticCurveTo(0,-47+bob,10,-53+bob);ctx.stroke();
 if(kind==='player'){rr(-11,-43+bob,22,6,2,'#263828');ctx.fillStyle='#c8f366';ctx.font='bold 6px sans-serif';ctx.fillText('KYIV',-8,-38+bob)}else{ctx.fillStyle='#e3c9aa';ctx.beginPath();ctx.moveTo(-5,-81+bob);ctx.lineTo(0,-91+bob);ctx.lineTo(4,-80+bob);ctx.fill()}
 if(attack>0){ctx.strokeStyle=kind==='player'?'#d8ff7c':'#ffc17b';ctx.globalAlpha=Math.min(.75,attack*3);ctx.lineWidth=4;ctx.beginPath();ctx.arc(side*21,-35+bob,24,-.8,.85);ctx.stroke();ctx.globalAlpha=1}
 ctx.restore();
}
function drawCar(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ellipse(0,0,53,13,'#151b18');poly([[-50,-12],[-40,-29],[-20,-39],[22,-37],[43,-24],[54,-12],[49,0],[-46,0]],'#8f4e3e','#d7ae7b',1.2);poly([[-29,-29],[-17,-36],[18,-34],[34,-24],[-31,-24]],'#7d9a94');rr(-45,-15,89,6,2,'#d7c78c');ellipse(-31,-1,8,5,'#20231f');ellipse(34,-1,8,5,'#20231f');ctx.restore()}
function drawScene(){ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));background();drawCar(screenX(255),groundY(.22),.55);drawCar(screenX(862),groundY(.28),.66);
 const ordered=[...actors,{...player,isPlayer:true}].sort((a,b)=>a.z-b.z);
 for(const a of ordered){const x=screenX(a.x),y=groundY(a.z);if(x<-100||x>1100)continue;const s=.53+a.z*.7;drawShadow(x,y,s);if(a.isPlayer)drawToad(x,y,s,a.face,a.step,'player',a.attack,a.invuln);else{drawToad(x,y,s,a.face,a.step,a.kind,a.attack,0);if(a.hp<a.max){ctx.fillStyle='#111';ctx.fillRect(x-17*s,y-101*s,34*s,4);ctx.fillStyle='#ff755f';ctx.fillRect(x-17*s,y-101*s,34*s*clamp(a.hp/a.max,0,1),4)}}}
 // floating combat text and particles
 for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);if(p.type==='spark'){ctx.fillStyle=p.color;ctx.fillRect(p.x-cam+p.vx*p.age,p.y+p.vy*p.age,3,3)}else{ctx.strokeStyle=p.color;ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x-cam,p.y,p.rad*(1-p.life/p.max),0,Math.PI*2);ctx.stroke()}}ctx.globalAlpha=1;
 for(const f of floating){ctx.globalAlpha=clamp(f.life,0,1);ctx.textAlign='center';ctx.font=`900 ${f.size}px 'Barlow Condensed',sans-serif`;ctx.fillStyle=f.color;ctx.shadowColor='#17201a';ctx.shadowBlur=8;ctx.fillText(f.text,f.x-cam,f.y);ctx.shadowBlur=0}ctx.globalAlpha=1;ctx.textAlign='left';
 // vignette and hit tint
 if(player.hp<32){ctx.fillStyle=`rgba(184,40,34,${.12+Math.sin(performance.now()/170)*.06})`;ctx.fillRect(0,0,W,H)}
 ctx.restore();}

function burst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({type:'spark',x,y,vx:rand(-2.5,2.5),vy:rand(-3,1),age:0,life:rand(.22,.55),max:.55,color})}
function pop(text,x,y,color='#e8f3d9',size=22){floating.push({text,x,y,color,size,life:1,vy:rand(22,36)})}
function spawnEnemy(){const side=Math.random()<.5?-1:1;const x=clamp(player.x+side*rand(300,430),55,1545),z=rand(.3,.88),heavy=round>1&&Math.random()<Math.min(.4,.13*round);actors.push({x,z,hp:heavy?70:42,max:heavy?70:42,face:x<player.x?1:-1,step:rand(0,5),attack:0,attackCd:rand(.5,1.4),stun:0,kind:heavy?'heavy':'goon',speed:heavy?45:62,wind:0});}
function nextWave(){round++;spawnLeft=Math.min(3+round,10);spawnTimer=.45;player.hp=Math.min(player.max,player.hp+14);ui.wave.textContent=String(round).padStart(2,'0');pop('+14 HP',player.x,groundY(player.z)-72,'#c8f366',21);ui.toast.textContent=`ROUND ${round}`;ui.toast.classList.add('show');toastTimer=1.6;beep(540,.15,'triangle')}
function attack(type){if(!running||paused||gameOver||player.attackCd>0)return;player.attackType=type;player.attack=type==='kick'?.42:.31;player.attackCd=type==='kick'?.48:.35;player.combo++;player.comboTimer=1.25;beep(type==='kick'?110:180,type==='kick'?.14:.06,type==='kick'?'sawtooth':'square',.045);
 let hits=0;for(const e of actors){const dx=e.x-player.x,dz=Math.abs(e.z-player.z);const range=type==='kick'?126:93;if(Math.abs(dx)<range&&dz<.2&&(Math.sign(dx)===player.face||Math.abs(dx)<32)){const dmg=type==='kick'?32:22;e.hp-=dmg;e.stun=type==='kick'?.72:.48;e.x+=player.face*(type==='kick'?27:15);e.attack=type==='kick'?.32:.22;hits++;burst(e.x,groundY(e.z)-45,Math.random()<.5?'#e4f97e':'#ffb070',type==='kick'?13:8);pop(type==='kick'?'KRAK!':'WHAP!',e.x,groundY(e.z)-78,type==='kick'?'#ffcb71':'#dbf686',type==='kick'?23:19);shake=type==='kick'?5:2.5;if(e.hp<=0){score+=e.kind==='heavy'?250:100;ui.score.textContent=String(score).padStart(4,'0');pop(e.kind==='heavy'?'BUSTED!':'+100',e.x,groundY(e.z)-107,'#c8f366',23);burst(e.x,groundY(e.z)-38,'#a9da55',15)}}}if(hits===0&&Math.random()<.55){ctx;}actors=actors.filter(e=>e.hp>0)}
function damagePlayer(amount,enemy){if(player.invuln>0||gameOver)return;player.hp=Math.max(0,player.hp-amount);player.invuln=.7;player.stun=.16;player.x+=Math.sign(player.x-enemy.x)*20;shake=7;burst(player.x,groundY(player.z)-45,'#ff7460',10);pop('+'+amount+'!',player.x,groundY(player.z)-85,'#ff7b69',24);beep(75,.19,'sawtooth',.05);if(player.hp<=0){gameOver=true;running=false;showCard('GAME OVER','THE STREETS ARE STILL OUT THERE.','You cleared '+score.toLocaleString()+' points worth of trouble across '+round+' round'+(round===1?'':'s')+'. Take a breath, then get back in the fight.','RUN IT BACK ↻')}}
function showCard(title,kicker,description,button){ui.overlay.innerHTML=`<section class="card"><span class="eyebrow">${kicker}</span><h1>${title.includes(' ')?title.replace(' ','<span>')+'</span>':title}</h1><p>${description}</p><div class="keys"><span class="key"><b>WASD</b> MOVE</span><span class="key"><b>J</b> PUNCH</span><span class="key"><b>K</b> KICK</span><span class="key"><b>SHIFT</b> DASH</span></div><button class="startbtn" id="restartBtn">${button}</button><div class="note">ONE TOAD. ONE CITY. ABSOLUTELY NO CHILL.</div></section>`;ui.overlay.classList.remove('hidden');document.querySelector('#restartBtn').onclick=resetGame}
function resetGame(){player.x=500;player.z=.62;player.hp=100;player.face=1;player.attack=player.attackCd=player.dash=player.dashCd=player.invuln=player.stun=player.combo=0;actors=[];particles=[];floating=[];score=0;round=1;spawnLeft=4;spawnTimer=.2;gameOver=false;paused=false;running=true;cam=0;ui.score.textContent='0000';ui.wave.textContent='01';ui.overlay.classList.add('hidden');ui.pause.textContent='Ⅱ  PAUSE';toast('ROUND 1');}
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=1.6}
function update(dt){if(!running||paused)return;dt=Math.min(dt,.035);player.step+=dt;player.attack=Math.max(0,player.attack-dt);player.attackCd=Math.max(0,player.attackCd-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.invuln=Math.max(0,player.invuln-dt);player.stun=Math.max(0,player.stun-dt);player.comboTimer-=dt;if(player.comboTimer<=0)player.combo=0;
 let dx=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0),dz=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0);const len=Math.hypot(dx,dz)||1;dx/=len;dz/=len;
 if(keys.has('Shift')&&player.dashCd<=0&&(dx||dz)&&player.stun<=0){player.dash=.18;player.dashCd=.8;player.invuln=.23;beep(290,.08,'triangle')};if(player.dash>0)player.dash=Math.max(0,player.dash-dt);
 const speed=player.dash>0?570:player.attack>0?115:215;if(player.stun<=0){player.x=clamp(player.x+dx*speed*dt,55,1545);player.z=clamp(player.z+dz*speed*dt,.12,.94);if(dx)player.face=Math.sign(dx);if(dx||dz)player.step+=dt*5}
 if((keys.has('j')||keys.has(' '))&&player.attackCd<=0)attack('punch');if(keys.has('k')&&player.attackCd<=0)attack('kick');
 cam+=(clamp(player.x-500,0,545)-cam)*Math.min(1,dt*4);
 if(spawnLeft>0){spawnTimer-=dt;if(spawnTimer<=0){spawnEnemy();spawnLeft--;spawnTimer=rand(.65,1.15)}}
 for(const e of actors){e.step+=dt;e.attack=Math.max(0,e.attack-dt);e.attackCd-=dt;e.stun=Math.max(0,e.stun-dt);const vx=player.x-e.x,vz=player.z-e.z,dist=Math.hypot(vx,vz*560);e.face=vx<0?-1:1;if(e.stun<=0){if(Math.abs(vx)>57||Math.abs(vz)>.075){const l=Math.hypot(vx,vz*560)||1;e.x+=vx/l*e.speed*dt;e.z+=vz/l*e.speed/560*dt}else if(e.attackCd<=0){e.attackCd=rand(1.05,1.7);e.attack=.35;e.wind=.19;setTimeout(()=>{if(!paused&&running&&Math.abs(e.x-player.x)<93&&Math.abs(e.z-player.z)<.17)damagePlayer(e.kind==='heavy'?14:9,e)},160);}}
 }
 actors=actors.filter(e=>e.hp>0);if(spawnLeft===0&&actors.length===0)nextWave();
 for(const p of particles){p.age+=dt;p.life-=dt;p.x+=p.vx;p.y+=p.vy;p.vy+=6*dt}particles=particles.filter(p=>p.life>0);for(const f of floating){f.life-=dt;f.y-=f.vy*dt}floating=floating.filter(f=>f.life>0);shake=Math.max(0,shake-dt*18);toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');
 ui.health.style.width=`${player.hp}%`;ui.health.style.background=player.hp<30?'#ff715f':'#c8f366';ui.healthNum.textContent=player.hp;
}
function frame(t){const dt=(t-last)/1000||0;last=t;update(dt);drawScene();requestAnimationFrame(frame)}requestAnimationFrame(frame);
